// A common security mistake: storing sensitive data in a JWS
String sensitiveData = "{\"userId\": 123, \"role\": \"ADMIN\", \"ssn\": \"000-00-0000\"}";
String encodedPayload = Base64.getUrlEncoder().encodeToString(sensitiveData.getBytes());

// The client can trivially decode this:
String decoded = new String(Base64.getUrlDecoder().decode(encodedPayload));
System.out.println(decoded); // Prints the sensitive SSN!
